actions.script:
operatorName = '' if (session?.operatorPartyId) { def opPerson = ec.entity.find("mantle.party.Person") .condition("partyId", session.operatorPartyId).one() if (opPerson) operatorName = [(opPerson.firstName ?: ''), (opPerson.lastName ?: '')].findAll{it}.join(' ') }
storeAddr = '' if (rTpl) { storeAddr = [rTpl.addressLine1, rTpl.addressLine2, rTpl.city, rTpl.state, rTpl.pincode].findAll{it}.join(', ') }
storeName = rTpl?.companyName ?: terminal?.terminalName ?: 'Store' storePhone = rTpl?.phone ?: '' storeEmail = rTpl?.email ?: '' taxReg = rTpl?.taxRegistrationNumber ?: terminal?.taxRegistrationNumber ?: '' headerText = rTpl?.headerText ?: '' footerText = rTpl?.footerText ?: '' termsText = rTpl?.termsText ?: ''
// FOP's bundled base fonts do not contain the rupee glyph. Use a readable currency prefix. cs = 'Rs. ' billNo = txn.transactionNumber ?: txn.transactionId billDate = ec.l10n.format(txn.entryDate, 'dd/MM/yyyy hh:mm a') customerName = txn.customerName ?: 'Walk-In Customer' customerPhone = txn.customerPhone ?: ''
totalQty = items.sum { (it.quantity ?: 0) as BigDecimal } ?: 0 totalSaving = BigDecimal.ZERO items.each { def mrp = (it.mrp ?: it.unitPrice ?: 0) as BigDecimal def rate = (it.unitPrice ?: 0) as BigDecimal def qty = (it.quantity ?: 0) as BigDecimal def saving = (mrp - rate) * qty if (saving > 0) totalSaving += saving } paidTotal = payments.sum { (it.amount ?: 0) as BigDecimal } ?: 0 // ZE-POS-005: credit/pay-later marker + amount due, computed in Groovy (no FO FreeMarker arithmetic) isCreditBill = (txn.isCredit == 'Y') outstandingAmt = zinr.inr(ec.l10n.format(((txn.payableAmount ?: 0) as BigDecimal) - ((txn.paidAmount ?: 0) as BigDecimal), '#,##0.00'))
